<?php
require __DIR__.'/bootstrap.php';
$conditions=['p.active=1'];$params=[];
if(!empty($_GET['q'])){$conditions[]='(p.name LIKE ? OR p.sku LIKE ? OR p.description LIKE ?)';$v='%'.trim($_GET['q']).'%';array_push($params,$v,$v,$v);}
if(!empty($_GET['category'])){$conditions[]='p.category_id=?';$params[]=(int)$_GET['category'];}
if(isset($_GET['featured']))$conditions[]='p.featured=1';
if(isset($_GET['min'])&&is_numeric($_GET['min'])){$conditions[]='COALESCE(NULLIF(p.sale_price,0),p.price)>=?';$params[]=(float)$_GET['min'];}
if(isset($_GET['max'])&&is_numeric($_GET['max'])){$conditions[]='COALESCE(NULLIF(p.sale_price,0),p.price)<=?';$params[]=(float)$_GET['max'];}
$order=['newest'=>'p.created_at DESC','price_asc'=>'COALESCE(NULLIF(p.sale_price,0),p.price) ASC','price_desc'=>'COALESCE(NULLIF(p.sale_price,0),p.price) DESC','name'=>'p.name ASC'][$_GET['sort']??'newest']??'p.created_at DESC';
$page=max(1,(int)($_GET['page']??1));$limit=12;$where=implode(' AND ',$conditions);$q=$pdo->prepare("SELECT COUNT(*) FROM products p WHERE $where");$q->execute($params);$total=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY $order LIMIT $limit OFFSET ".(($page-1)*$limit));$q->execute($params);$products=$q->fetchAll();$categories=$pdo->query('SELECT id,name FROM categories WHERE active=1 ORDER BY name')->fetchAll();site_header($pdo,'Shop'); ?>
<section class="page-intro"><span class="eyebrow">THE COLLECTION</span><h1>Shop all</h1><p>Considered pieces for living beautifully.</p></section><section class="section"><form class="filters" method="get"><input name="q" placeholder="Search products" value="<?=e($_GET['q']??'')?>"><select name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" <?=((string)($_GET['category']??'')===(string)$c['id']?'selected':'')?>><?=e($c['name'])?></option><?php endforeach; ?></select><input name="min" type="number" min="0" placeholder="Min price" value="<?=e($_GET['min']??'')?>"><input name="max" type="number" min="0" placeholder="Max price" value="<?=e($_GET['max']??'')?>"><select name="sort"><option value="newest">Newest</option><option value="price_asc" <?=($_GET['sort']??'')==='price_asc'?'selected':''?>>Price: low to high</option><option value="price_desc" <?=($_GET['sort']??'')==='price_desc'?'selected':''?>>Price: high to low</option><option value="name" <?=($_GET['sort']??'')==='name'?'selected':''?>>Name A–Z</option></select><button class="button" type="submit">FILTER</button></form><p class="muted"><?=$total?> products</p><div class="product-grid"><?php foreach($products as $p): ?><article class="product-card"><a href="product.php?slug=<?=e($p['slug'])?>"><div class="product-image"><img src="<?=e(product_image($p['image']))?>" alt="<?=e($p['name'])?>" loading="lazy"></div><div class="product-meta"><span><?=e($p['category_name']??'Collection')?></span><h3><?=e($p['name'])?></h3><b><?=money((float)($p['sale_price']?:$p['price']))?></b></div></a></article><?php endforeach; ?></div><?php if(!$products): ?><div class="empty-state">No products found. Try adjusting your search.</div><?php endif; ?><div class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++): ?><a class="<?=($i===$page?'current':'')?>" href="?<?=http_build_query(array_merge($_GET,['page'=>$i]))?>"><?=$i?></a><?php endfor; ?></div></section><?php site_footer($pdo); ?>
